/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

/**
 * Inline text supports `[1]` and `[1, 3]` citations, `**bold**`, `*italic*`, `` `code` `` and
 * `[links](https://...)`. Citations number into `sources`, starting at 1.
 */
export type ResearchReportInline = string

export type ResearchReportBlock =
  | ResearchReportInline
  | { type: "p"; text: ResearchReportInline }
  | { type: "h3"; text: string }
  | { type: "list"; items: ResearchReportInline[]; ordered?: boolean }
  | { type: "quote"; text: ResearchReportInline; cite?: ResearchReportInline }
  | { type: "table"; head: string[]; rows: ResearchReportInline[][]; caption?: string }
  /** Anything custom, such as a chart. `markdown` is what exports get instead. */
  | { type: "node"; node: React.ReactNode; markdown?: string }

export interface ResearchReportSection {
  id: string
  title: string
  blocks: ResearchReportBlock[]
}

/* -------------------------------------------------------------------------------------------------
 * Types and helpers
 * -----------------------------------------------------------------------------------------------*/

interface Source {
  /** Stable id, for example the AI SDK `sourceId`. Defaults to the URL. */
  id?: string
  url: string
  title?: string
  snippet?: string
  /** Defaults to the URL host without `www.`. */
  domain?: string
  /** Optional favicon URL. Falls back to a monochrome letter tile when missing or broken. */
  favicon?: string
}

interface CitationSource extends Source {
  /** The exact passage that supports the claim. Highlighted inside `snippet` when found there. */
  quote?: string
}

export interface ResearchReportSource extends CitationSource {
  /** Author and year, or the publisher, shown under the title in the sources list. */
  byline?: string
}

export interface ResearchReportProps extends Omit<React.ComponentProps<"article">, "title"> {
  title: string
  /** One or two sentences under the title. */
  dek?: ResearchReportInline
  sections: ResearchReportSection[]
  sources: ResearchReportSource[]
  /** Shown in the meta line, for example "Oct 21, 2026". */
  date?: string
  /** Sources read during the run, when more than the ones cited. */
  sourcesRead?: number
  /** The report is still being written: the last block gets the caret and the TOC fills in. */
  streaming?: boolean
  /** `comfortable` sets prose at 16/26, `default` at 15/24. */
  density?: "default" | "comfortable"
  /** Show the sticky table of contents when there is room. On by default. */
  toc?: boolean
  /** Extra actions after Copy and Download. */
  actions?: React.ReactNode
  /** Download file name. Defaults to the title as a slug. */
  filename?: string
  /** Replace the built-in copy. Receives the Markdown. */
  onCopyMarkdown?: (markdown: string) => void
  /** Replace the built-in download. Receives the Markdown. */
  onDownload?: (markdown: string) => void
  /** Words per minute for the reading time. Defaults to 230. */
  wordsPerMinute?: number
}

/** Host of a URL without `www.`, or the input when it is not a URL. */
function getSourceDomain(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "")
  } catch {
    return url
  }
}

/** The report as GitHub-flavored Markdown with a numbered sources list. */
export function researchReportToMarkdown({
  title,
  dek,
  sections,
  sources,
}: Pick<ResearchReportProps, "title" | "dek" | "sections" | "sources">) {
  const lines: string[] = [`# ${title}`, ""]
  if (dek) lines.push(dek, "")
  for (const section of sections) {
    lines.push(`## ${section.title}`, "")
    for (const block of section.blocks) {
      if (typeof block === "string") lines.push(block, "")
      else if (block.type === "p") lines.push(block.text, "")
      else if (block.type === "h3") lines.push(`### ${block.text}`, "")
      else if (block.type === "quote")
        lines.push(`> ${block.text}${block.cite ? `\n>\n> ${block.cite}` : ""}`, "")
      else if (block.type === "list")
        lines.push(
          ...block.items.map((item, i) => `${block.ordered ? `${i + 1}.` : "-"} ${item}`),
          "",
        )
      else if (block.type === "table") {
        const row = (cells: string[]) =>
          `| ${cells.map((c) => c.replace(/\|/g, "\\|")).join(" | ")} |`
        lines.push(row(block.head), row(block.head.map(() => "---")), ...block.rows.map(row), "")
      } else if (block.markdown) lines.push(block.markdown, "")
    }
  }
  if (sources.length > 0) {
    lines.push("## Sources", "")
    sources.forEach((s, i) => {
      const label = s.title ?? getSourceDomain(s.url)
      lines.push(`${i + 1}. [${label}](${s.url})${s.byline ? `, ${s.byline}` : ""}`)
    })
    lines.push("")
  }
  return lines.join("\n")
}

interface UseChatcnResearchTocOptions {
  /** Section ids in document order. */
  ids: string[]
  /** Finds the element for an id. Defaults to `document.getElementById`. */
  getElement?: (id: string) => HTMLElement | null
  /**
   * Where the reading line sits, as a fraction of the scroll viewport from its top. A section is
   * active once its heading has passed this line. Defaults to 0.2.
   */
  offset?: number
  /** Turn tracking off, for example while the table of contents is hidden. */
  enabled?: boolean
}

interface UseChatcnResearchTocResult {
  /** The section the reader is in. */
  activeId: string | undefined
  /**
   * Mark a section active right away, for example after a table of contents click, so the
   * highlight does not lag behind a smooth scroll.
   */
  setActiveId: (id: string) => void
}

/** Nearest ancestor that scrolls vertically, or `null` for the window. */
function getChatcnScrollParent(el: HTMLElement | null): HTMLElement | null {
  let node = el?.parentElement ?? null
  while (node && node !== document.body && node !== document.documentElement) {
    const { overflowY } = getComputedStyle(node)
    if (overflowY === "auto" || overflowY === "scroll") return node
    node = node.parentElement
  }
  return null
}

/**
 * Scroll spy for a long report: returns the id of the section whose heading most recently passed
 * the reading line, in the window or in whichever ancestor scrolls. At the very bottom the last
 * section wins, so a short closing section can still become active.
 *
 * Reads layout once per animation frame while scrolling and never writes to the DOM.
 */
function useChatcnResearchToc({
  ids,
  getElement,
  offset = 0.2,
  enabled = true,
}: UseChatcnResearchTocOptions): UseChatcnResearchTocResult {
  const [activeId, setActive] = React.useState<string | undefined>(ids[0])
  const lock = React.useRef<{ id: string; until: number } | null>(null)
  const key = ids.join("\n")
  const getRef = React.useRef(getElement)
  getRef.current = getElement

  React.useEffect(() => {
    if (!enabled || ids.length === 0) return
    const find = (id: string) => getRef.current?.(id) ?? document.getElementById(id)
    const first = find(ids[0] as string)
    const root = getChatcnScrollParent(first)
    const target: HTMLElement | Window = root ?? window
    let frame = 0

    const measure = () => {
      frame = 0
      // A table of contents click scrolls smoothly; hold its choice until the scroll settles.
      if (lock.current && performance.now() < lock.current.until) return
      lock.current = null
      const top = root ? root.getBoundingClientRect().top : 0
      const height = root ? root.clientHeight : window.innerHeight
      const line = top + height * offset
      const scrolled = root
        ? root.scrollTop + root.clientHeight >= root.scrollHeight - 2
        : window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 2
      let next = ids[0]
      if (scrolled) next = ids[ids.length - 1]
      else {
        for (const id of ids) {
          const el = find(id)
          if (!el) continue
          if (el.getBoundingClientRect().top <= line) next = id
          else break
        }
      }
      setActive((prev) => (prev === next ? prev : next))
    }
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(measure)
    }
    measure()
    target.addEventListener("scroll", onScroll, { passive: true })
    window.addEventListener("resize", onScroll)
    return () => {
      target.removeEventListener("scroll", onScroll)
      window.removeEventListener("resize", onScroll)
      if (frame) cancelAnimationFrame(frame)
    }
  }, [key, offset, enabled])

  const setActiveId = React.useCallback((id: string) => {
    lock.current = { id, until: performance.now() + 900 }
    setActive(id)
  }, [])

  return { activeId: activeId && ids.includes(activeId) ? activeId : ids[0], setActiveId }
}

/** Plain words of an inline string, for reading time and exports. */
function plainText(text: string) {
  return text
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, "$1")
    .replace(/\s*\[\d+(?:\s*,\s*\d+)*\]/g, "")
    .replace(/\*\*|`|\*/g, "")
}

/* -------------------------------------------------------------------------------------------------
 * Markdown export and reading time
 * -----------------------------------------------------------------------------------------------*/

function blockText(block: ResearchReportBlock): string {
  if (typeof block === "string") return plainText(block)
  switch (block.type) {
    case "p":
    case "h3":
      return plainText(block.text)
    case "quote":
      return plainText(`${block.text} ${block.cite ?? ""}`)
    case "list":
      return block.items.map(plainText).join(" ")
    case "table":
      return [...block.head, ...block.rows.flat()].map(plainText).join(" ")
    case "node":
      return block.markdown ?? ""
  }
}

function countWords(sections: ResearchReportSection[], extra = "") {
  const text = `${extra} ${sections.map((s) => `${s.title} ${s.blocks.map(blockText).join(" ")}`).join(" ")}`
  return text.split(/\s+/).filter(Boolean).length
}

interface InlineContext {
  sources: ResearchReportSource[]
  onCite: (index: number, event: React.MouseEvent<HTMLAnchorElement>) => void
}

type StreamingCaretStatus = "streaming" | "waiting" | "done"

interface StreamingCaretProps extends Omit<React.ComponentProps<"span">, "children"> {
  /**
   * `streaming` is solid, `waiting` blinks slowly, `done` removes the caret. Defaults to
   * `streaming`.
   */
  status?: StreamingCaretStatus
  /**
   * Pass the streamed text (or anything that changes with each token). While it keeps changing
   * the caret stays solid; once it holds still for `idleMs` the caret starts to blink.
   */
  activity?: unknown
  /** Quiet time before the caret switches to blinking. Defaults to 600 ms. */
  idleMs?: number
}

/**
 * The signature mark: a small rounded square that means "the model is writing here". It sits on
 * the text baseline at 0.55em, so it scales with whatever text it follows. Solid while tokens flow,
 * a slow 1.2 s blink only while waiting, gone when done. Static under reduced motion.
 */
function StreamingCaret({
  status = "streaming",
  activity,
  idleMs = 600,
  className,
  ...props
}: StreamingCaretProps) {
  const [idle, setIdle] = React.useState(false)
  const tracking = activity !== undefined && status === "streaming"

  React.useEffect(() => {
    if (!tracking) return
    setIdle(false)
    const id = window.setTimeout(() => setIdle(true), idleMs)
    return () => window.clearTimeout(id)
  }, [activity, tracking, idleMs])

  if (status === "done") return null
  const blinking = status === "waiting" || (tracking && idle)

  return (
    <span
      aria-hidden="true"
      data-slot="streaming-caret"
      data-caret-state={blinking ? "waiting" : "streaming"}
      className={cn(
        "bg-(color:--chatcn-accent) ms-0.5 inline-block size-[0.55em] translate-y-[0.04em] rounded-[0.12em] align-baseline forced-colors:bg-[CanvasText]",
        blinking &&
          "animate-[chatcn-caret-blink_1.2s_steps(1,end)_infinite] motion-reduce:animate-none",
        className,
      )}
      {...props}
    />
  )
}

/* -------------------------------------------------------------------------------------------------
 * Inline parsing
 * -----------------------------------------------------------------------------------------------*/

const INLINE =
  /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)|((?:\s*\[\d+(?:\s*,\s*\d+)*\])+)|\*\*([^*]+)\*\*|`([^`]+)`|\*([^*\s][^*]*)\*/g

function citationNumbers(match: string) {
  return Array.from(match.matchAll(/\d+/g), (m) => Number(m[0]))
}

interface CitationProps extends Omit<React.ComponentProps<"a">, "href" | "children"> {
  /** The number shown, matching the position in `Sources`. */
  index: number
  source: CitationSource
  /** `inline` is a small pill on the baseline; `superscript` is a raised number. */
  variant?: "inline" | "superscript"
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

function useCoarsePointer() {
  const [coarse, setCoarse] = React.useState(false)
  React.useEffect(() => {
    const mq = window.matchMedia("(pointer: coarse)")
    const update = () => setCoarse(mq.matches)
    update()
    mq.addEventListener("change", update)
    return () => mq.removeEventListener("change", update)
  }, [])
  return coarse
}

/* -------------------------------------------------------------------------------------------------
 * SourceTile
 * -----------------------------------------------------------------------------------------------*/

interface SourceTileProps extends React.ComponentProps<"span"> {
  source: Pick<Source, "url" | "domain" | "favicon">
}

/**
 * A favicon slot. Without a favicon it shows the domain's first letter on a gray tile: no brand
 * colors, so a row of sources stays as calm as the text around it.
 */
function SourceTile({ source, className, ...props }: SourceTileProps) {
  const [broken, setBroken] = React.useState(false)
  const domain = source.domain ?? getSourceDomain(source.url)
  const letter =
    domain
      .replace(/^[^a-z0-9]+/i, "")
      .charAt(0)
      .toUpperCase() || "?"
  return (
    <span
      data-slot="source-tile"
      aria-hidden="true"
      className={cn(
        "bg-(color:--chatcn-fill-active) text-(color:--chatcn-fg-muted) rounded-(--chatcn-radius-xs) relative grid size-[1.125rem] shrink-0 place-items-center overflow-hidden",
        "text-[0.75rem]/[1rem] leading-none font-medium select-none",
        className,
      )}
      {...props}
    >
      {source.favicon && !broken ? (
        <img
          src={source.favicon}
          alt=""
          width={18}
          height={18}
          loading="lazy"
          onError={() => setBroken(true)}
          className="size-full object-cover"
        />
      ) : (
        letter
      )}
    </span>
  )
}

/** Splits the snippet around the quote so the supporting passage can be highlighted. */
function highlight(snippet: string, quote?: string): React.ReactNode {
  if (!quote) return snippet
  const at = snippet.toLowerCase().indexOf(quote.toLowerCase())
  if (at < 0) return snippet
  return (
    <>
      {snippet.slice(0, at)}
      <mark className="bg-(color:--chatcn-fill-active) text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) box-decoration-clone px-0.5 py-px">
        {snippet.slice(at, at + quote.length)}
      </mark>
      {snippet.slice(at + quote.length)}
    </>
  )
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes[size])
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
