function renderInline(text: string, ctx: InlineContext): React.ReactNode[] {
  const out: React.ReactNode[] = []
  let last = 0
  let key = 0
  for (const m of text.matchAll(INLINE)) {
    const at = m.index ?? 0
    if (at > last) out.push(text.slice(last, at))
    last = at + m[0].length
    const [, linkText, linkUrl, cites, bold, code, em] = m
    if (linkText && linkUrl) {
      out.push(
        <a
          key={key++}
          href={linkUrl}
          target="_blank"
          rel="noreferrer"
          className={cn(
            "text-(color:--chatcn-fg) decoration-(color:--chatcn-border-strong) underline decoration-1 underline-offset-[0.22em]",
            "ease-(--chatcn-ease-standard) hover:decoration-(color:--chatcn-fg) chatcn-focus rounded-[2px] transition-[text-decoration-color] duration-150",
          )}
        >
          {linkText}
        </a>,
      )
    } else if (cites) {
      // Citations hug the word before them: the leading space is part of the match and dropped.
      const nums = citationNumbers(cites)
      out.push(
        <span key={key++} className="whitespace-nowrap">
          {nums.map((n, i) => {
            const source = ctx.sources[n - 1]
            const comma =
              i > 0 ? (
                <sup
                  aria-hidden="true"
                  className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) top-[-0.4em]"
                >
                  ,
                </sup>
              ) : null
            if (!source)
              return (
                <React.Fragment key={n}>
                  {comma}
                  <sup>{n}</sup>
                </React.Fragment>
              )
            return (
              <React.Fragment key={n}>
                {comma}
                <Citation
                  index={n}
                  source={source}
                  variant="superscript"
                  onClick={(event) => ctx.onCite(n, event)}
                />
              </React.Fragment>
            )
          })}
        </span>,
      )
    } else if (bold) {
      out.push(
        <strong key={key++} className="text-(color:--chatcn-fg) font-semibold">
          {bold}
        </strong>,
      )
    } else if (code) {
      out.push(
        <code
          key={key++}
          className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) px-1 py-px font-mono text-[0.875em] whitespace-nowrap"
        >
          {code}
        </code>,
      )
    } else if (em) {
      out.push(<em key={key++}>{em}</em>)
    }
  }
  if (last < text.length) out.push(text.slice(last))
  return out
}

