            <h1 className="text-[2rem]/[2.5rem] tracking-[-0.028em] text-(color:--chatcn-fg) font-semibold text-balance">{title}</h1>
            {dek ? (
              <p className="text-[1.125rem]/[1.625rem] tracking-[-0.015em] text-(color:--chatcn-fg-muted) text-pretty">
                {renderInline(dek, ctx)}
              </p>
            ) : null}
            <div className="border-(color:--chatcn-border) mt-2 flex flex-wrap items-center gap-x-4 gap-y-3 border-y py-3">
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) me-auto flex flex-wrap gap-x-1.5 tabular-nums">
                <span>{streaming ? "Writing" : `${minutes} min read`}</span>
                <span aria-hidden="true">·</span>
                <span>
                  {sources.length} {sources.length === 1 ? "source" : "sources"} cited
                  {sourcesRead && sourcesRead > sources.length ? ` of ${sourcesRead} read` : ""}
                </span>
                {date ? (
                  <>
                    <span aria-hidden="true">·</span>
                    <span>{date}</span>
                  </>
                ) : null}
              </p>
              <div className="flex items-center gap-1.5">
                <CopyMarkdownButton getValue={markdown} onCopy={onCopyMarkdown} />
                <Button
                  size="sm"
                  variant="outline"
                  disabled={streaming}
                  className="pointer-coarse:h-11"
                  onClick={() => {
                    const md = markdown()
                    if (onDownload) return onDownload(md)
                    const url = URL.createObjectURL(new Blob([md], { type: "text/markdown" }))
                    const a = document.createElement("a")
                    a.href = url
                    a.download = `${filename ?? slugify(title)}.md`
                    a.click()
                    window.setTimeout(() => URL.revokeObjectURL(url), 1000)
                  }}
                >
                  <DownloadIcon />
                  Download
                </Button>
                {actions}
              </div>
            </div>
          </header>

          <div className={cn(prose, "text-(color:--chatcn-fg)")}>
            {sections.map((section, s) => (
              <section
                key={section.id}
                aria-labelledby={sectionDomId(section.id)}
                className="ease-(--chatcn-ease-out-soft) transition-opacity duration-150 starting:opacity-0"
              >
                <h2
                  id={sectionDomId(section.id)}
                  tabIndex={-1}
                  className="text-[1.25rem]/[1.75rem] tracking-[-0.018em] text-(color:--chatcn-fg) mt-10 mb-4 scroll-mt-8 font-semibold text-balance outline-none"
                >
                  {section.title}
                </h2>
                <div className="flex flex-col gap-5">
                  {section.blocks.map((block, b) => (
                    <ReportBlock
                      key={b}
                      block={block}
                      ctx={ctx}
                      caret={caretFor(s, b, section.blocks.length)}
                    />
                  ))}
                  {streaming && s === lastSection && section.blocks.length === 0 ? (
                    <p>
                      <StreamingCaret status="waiting" />
                    </p>
                  ) : null}
                </div>
              </section>
            ))}
          </div>

          {sources.length > 0 && !streaming ? (
            <section aria-labelledby={sourcesId} className="mt-12">
              <h2
                id={sourcesId}
                tabIndex={-1}
                className="text-[1.25rem]/[1.75rem] tracking-[-0.018em] text-(color:--chatcn-fg) mb-3 scroll-mt-8 font-semibold outline-none"
              >
                Sources
              </h2>
              <ol className="flex flex-col">
                {sources.map((source, i) => {
                  const n = i + 1
                  const domain = source.domain ?? getSourceDomain(source.url)
                  return (
                    <li key={source.id ?? source.url}>
                      <a
                        id={`${uid}-source-${n}`}
                        href={source.url}
                        target="_blank"
                        rel="noreferrer"
                        data-flash={flash === n || undefined}
                        className={cn(
                          "chatcn-focus rounded-(--chatcn-radius-md) -mx-2 grid scroll-mt-8 grid-cols-[1.5rem_1fr] gap-x-2 px-2 py-2.5",
                          "ease-(--chatcn-ease-standard) transition-colors duration-150",
                          "hover:bg-(color:--chatcn-fill-hover) data-[flash]:bg-(color:--chatcn-fill-active)",
                        )}
                      >
                        <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) pt-px text-end font-medium tabular-nums">
                          {n}
                        </span>
                        <span className="flex min-w-0 flex-col gap-0.5">
                          <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium text-pretty">
                            {source.title ?? domain}
                          </span>
                          <span className="flex min-w-0 items-center gap-1.5">
                            <SourceTile source={source} className="size-4" />
                            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate">
                              {source.byline ? `${source.byline} · ${domain}` : domain}
                            </span>
                          </span>
                        </span>
                      </a>
                    </li>
                  )
                })}
              </ol>
            </section>
          ) : null}
        </div>
      </div>
    </article>
  )
}

export default ResearchReport

